  const selected=new Set([directory]),missing=new Set(),parentDirectories=new Set(),summaries=[];
  const requireInside=path=>{
    absolute(path);need(inside(stateRoot,path),'WORKSPACE_RECOVERY_DEPENDENCY_OUTSIDE_ROOT');
    return path;
  };
