  const jobs = await queue.list();
  need(saved.buyers.length === jobs.length && saved.buyers.every(entry =>
    jobs.some(job => job.operation?.intentId === entry.intentId)), 'COMMERCE_INBOX_MEMBERSHIP_CHANGED');
